        {"unit": "GUNIT97", "title": "My Legacy", "canDo": "I can talk about legacy", "dialoguePlace": "Home", "readingText": "Legacy is what remains after you. Not money. Not houses. But what you taught, what you built, who you helped. My grandmother left stories. My mother left kindness. What will I leave? I want to leave an English school for East African adults and children. That is my legacy.", "readingWords": 58, "vocab": ["Legacy", "Remains", "Taught", "Built", "Helped"], "grammar": "What will I leave?", "tryAtHome": "Write your legacy sentence"},
        {"unit": "GUNIT98", "title": "Writing a Book", "canDo": "I can plan a book", "dialoguePlace": "Writer Room", "readingText": "Mary wants to write a book: English for East African Adults. Chapter 1: Hello. Chapter 2: My Family. Chapter 3: My Region. She will write one page per day. In 100 days, she will have 100 pages. Writing a book needs discipline, not talent. Start with one page. John will help with business chapter.", "readingWords": 62, "vocab": ["Chapter", "Discipline", "Talent", "Page", "Write"], "grammar": "She will write...", "tryAtHome": "Write 1 page of your book"},
        {"unit": "GUNIT99", "title": "Mentoring Youth", "canDo": "I can mentor", "dialoguePlace": "Youth Center", "readingText": "A mentor guides, not controls. John mentors younger adults in Nairobi. He listens to their fears. He shares his mistakes. He encourages them. He says: I was like you. You can do it. Mentoring multiplies hope. One mentor can change 100 lives. Mary mentors young teachers in Arusha.", "readingWords": 58, "vocab": ["Mentor", "Guides", "Encourages", "Multiplies", "Hope"], "grammar": "A mentor guides...", "tryAtHome": "Mentor 1 younger adult"},
        {"unit": "GUNIT100", "title": "Isomero Vision - EAC", "canDo": "I can present vision", "dialoguePlace": "Isomero Office - Arusha", "readingText": "Isomero means learning. Our vision: Every East African adult and child speaks English with confidence. We will build apps, clubs, and schools. We will train teachers. We will use Swahili to teach English. We will keep culture. We will open doors. Isomero is not just an app. It is a movement. From Burundi to Somalia, we are one. Mary and John lead it.", "readingWords": 64, "vocab": ["Vision", "Confidence", "Movement", "Train", "Culture"], "grammar": "Our vision: Every child...", "tryAtHome": "Present Isomero vision"},
        {"unit": "GUNIT101", "title": "Global Speaker", "canDo": "I can speak globally", "dialoguePlace": "TED Stage", "readingText": "Hello, world. I am Mary from East Africa. I am 26, a teacher from Arusha. I come from hills and drums. I learned English in a small classroom with no internet. Today, I speak to you. My message is simple: Language is power. Education is freedom. If a woman from Arusha can speak, anyone can. Never underestimate an adult with a book. John is with me today from Nairobi.", "readingWords": 70, "vocab": ["Global", "Underestimate", "Freedom", "Power", "Message"], "grammar": "I come from...", "tryAtHome": "Record 2 min TED talk"},
        {"unit": "GUNIT102", "title": "Research Project", "canDo": "I can present research", "dialoguePlace": "University", "readingText": "My research asks: Does English help East African adults get jobs? I interviewed 50 adults in Arusha, Nairobi and Kampala. 80% said English helped. 60% got better jobs. 90% want more English clubs. Conclusion: English opens opportunities. Recommendation: Teach English from Pre-A1 with local stories for adults in East Africa. Data speaks.", "readingWords": 60, "vocab": ["Research", "Interviewed", "Conclusion", "Recommendation", "Data"], "grammar": "My research asks...", "tryAtHome": "Interview 3 people"},
        {"unit": "GUNIT103", "title": "Building a School", "canDo": "I can plan a school", "dialoguePlace": "Arusha", "readingText": "To build a school, we need land, bricks, teachers, and books. But most important, we need vision. Mary and John will start with one classroom for adults and children in Arusha. They will teach 30 adults. They will use Isomero curriculum. One classroom can become many. One teacher can change many lives. We start small. We dream big. East Africa needs schools.", "readingWords": 64, "vocab": ["Build", "Bricks", "Vision", "Classroom", "Dream big"], "grammar": "We need / We will start", "tryAtHome": "Draw your dream school"},
        {"unit": "GUNIT104", "title": "I Am East African - Graduation", "canDo": "I can present myself in English", "dialoguePlace": "Graduation - Arusha", "readingText": "Hello! My name is Mary. I am 26 years old. I am a teacher in Arusha, Tanzania. I started with Hello, I am Mary. Now I can speak, read, and present in English. I met John from Nairobi. We learned together. We are East Africans. We speak Swahili and English. We are proud. Thank you, Isomero. Thank you, teacher. Thank you, friends. I am ready. I am East African. I am ready for the world.", "readingWords": 78, "vocab": ["Graduation", "Proud", "Ready", "Thank you", "World"], "grammar": "I can speak / I am ready", "tryAtHome": "Present yourself in 1 minute in English"}
